{"command": "python3 - <<'EOF'
import json, glob, os, collections
totals=collections.defaultdict(int)
malformed=[]
cats=collections.Counter()
for p in sorted(glob.glob('orders/*.json')):
    name=os.path.basename(p)
    try:
        with open(p) as f: d=json.load(f)
    except Exception as e:
        malformed.append(name); continue
    cats[d['category']]+=1
    if d['category']!='refund':
        totals[d['category']]+=d['amount_cents']
print('malformed', malformed)
print('cats', cats)
print('totals', dict(totals))
# check schema oddities
for p in sorted(glob.glob('orders/*.json')):
    try:
        d=json.load(open(p))
    except Exception: continue
    if not isinstance(d,dict) or set(d)!={'id','category','amount_cents'} or not isinstance(d.get('amount_cents'),int) or not isinstance(d.get('category'),str):
        print('odd', p, d)
EOF", "description": "Parse orders and compute totals"}

